public class TinhToan {

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//Khai báo biến
		int a = 10;
		int b = 5;
		
		//Các phép tính
		int cong = a + b;
		int tru = a - b;
		int nhan = a * b;
		double chia = a / b;
		
		//In kết quả
		System.out.println("Cộng: " + cong);
		System.out.println("Trừ: " + tru);
		System.out.println("Nhân: " + nhan);
		System.out.println("Chia: " + chia);

	}

}
